-- 家庭料理の型と入れ替え候補。official_foods が揃っているときだけ入れる。
-- アプリには埋め込まない。足すときは recipes.ts を編集し、この SQL を出し直す。
-- 本番には適用しない。

do $$
declare
  present integer;
begin
  select count(*) into present
  from public.official_foods
  where food_code in ('01026', '01039', '01064', '01088', '01128', '02017', '03003', '04032', '04033', '04039', '04046', '06049', '06061', '06065', '06103', '06153', '06182', '06223', '06226', '06233', '06245', '06264', '06267', '06291', '10134', '10263', '11019', '11115', '11220', '11224', '12004', '13040', '14002', '14006', '14017', '16025', '17007', '17012', '17015', '17028', '17045', '17063', '17138');
  if present < 43 then
    raise notice 'cook recipes skipped: official_foods has % of 43 codes', present;
    return;
  end if;

  delete from public.cook_recipes;


end $$;

