    ('broccoli-grill', '{protein}とブロッコリーのグリル', '洋', '主菜', '焼', 5, '["{protein}と{veg}を食べやすく切る。","フライパンを中火にし、{oil}{g:oil}gを熱して{protein}を3分焼く。","{veg}を加えて2分炒め、しょうゆ{g:soy}gとみりん{g:mirin}gを絡める。","火を止めて器に盛る。","塩{g:salt}gとこしょう{g:pepper}gを加えて味をととのえる。"]'::jsonb),
    ('salmon-tomato-pasta', '鮭とトマトのパスタ', '洋', '丼麺', '炒', 9, '["スパゲティ{g:pasta}gを湯で6分ゆでる。","フライパンで{oil}{g:oil}gを熱し、{protein}と{veg}を2分炒める。","しょうゆ{g:soy}gとこしょう{g:pepper}gを加えて1分絡める。","ゆでたスパゲティを戻し入れて火を通し、器に盛る。"]'::jsonb),
    ('tuna-sandwich', 'ツナの焼きサンド', '洋', '軽い品', '焼', 5, '["食パン{g:bread}gに{protein}をのせる。","フライパンを弱火にし、バター{g:butter}gで2分焼く。","塩{g:salt}gとこしょう{g:pepper}gを振る。","3分加熱して中まで温まったら皿に出す。"]'::jsonb),
    ('ethnic-tomato', '{protein}とトマトの炒め', 'エスニック', '主菜', '炒', 5, '["{protein}と{veg}を食べやすく切る。","フライパンを中火にし、{oil}{g:oil}gを熱して{protein}を3分焼く。","{veg}を加えて2分炒め、しょうゆ{g:soy}gとみりん{g:mirin}gを絡める。","火を止めて器に盛る。"]'::jsonb),
    ('tuna-ethnic', 'ツナとキャベツのエスニック炒め', 'エスニック', '主菜', '炒', 5, '["{protein}と{veg}を食べやすく切る。","フライパンを中火にし、{oil}{g:oil}gを熱して{protein}を3分炒める。","{veg}と味噌{g:miso}gと砂糖{g:sugar}gと料理酒{g:sake}gを加えて2分炒め合わせる。","火を止めて器に盛る。"]'::jsonb),
    ('garlic-don', '{protein}のガーリック丼', 'エスニック', '丼麺', '焼', 5, '["{protein}を一口大に切る。{ginger}{g:ginger}gを添える。","フライパンを中火にし、{oil}{g:oil}gを熱して{protein}を3分焼く。","しょうゆ{g:soy}gとみりん{g:mirin}gを加えて2分絡め、中まで火を通す。","{rice}{g:rice}gを器に盛り、具をのせる。"]'::jsonb);
